    assert_eq!(candidate("word1 word2word3word4word5"), word1 word2word3word4word5);
    assert_eq!(candidate("multiple    spaces    between    words"), multiple    spaces    between    words);
    assert_eq!(candidate("multiple   spaces    between    words"), multiple   spaces   between   words  );
}
